mkdir -p /tmp/bot-check && cat > /tmp/bot-check/check.mjs <<'EOF'
import { reserve } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/baseline-g4-2/bot.mjs';
import { mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { execFileSync } from 'node:child_process';
import assert from 'node:assert/strict';

const H = 3600e3, D = 24 * H;
const base = new Date('2026-10-23T10:00:00Z');
const t = (ms) => new Date(base.getTime() + ms);
const dir = mkdtempSync(join(tmpdir(), 'bot-state-'));
process.env.STATE_DIR = join(dir, 'nested', 'state');

// 1. five allowed across mixed channels, sixth denied
const ch = ['sms', 'push', 'chat', 'sms', 'push'];
for (let i = 0; i < 5; i++) {
  const r = await reserve('cust-A', ch[i], t(i * H));
  assert.equal(r.allowed, true); assert.equal(r.retryAt, null);
}
let r = await reserve('cust-A', 'chat', t(5 * H));
assert.equal(r.allowed, false);
// oldest send at t=0 expires at t=24h
assert.equal(r.retryAt.getTime(), base.getTime() + D);
assert.match(r.reason, /5 proactive/);
console.log('reason:', r.reason);

// 2. denied calls count nothing: still denied just before expiry
r = await reserve('cust-A', 'sms', t(D - 1));
assert.equal(r.allowed, false);
assert.equal(r.retryAt.getTime(), base.getTime() + D);

// 3. exactly at retryAt it is allowed; then the next retry is the 2nd send + 24h
r = await reserve('cust-A', 'push', t(D));
assert.equal(r.allowed, true);
r = await reserve('cust-A', 'push', t(D + 1));
assert.equal(r.allowed, false);
assert.equal(r.retryAt.getTime(), base.getTime() + H + D);

// 4. other customer unaffected
r = await reserve('cust-B', 'sms', t(5 * H));
assert.equal(r.allowed, true);

// 5. retained state survives a fresh module instance (simulates restart)
const fresh = await import(`<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/baseline-g4-2/bot.mjs?restart=1`);
r = await fresh.reserve('cust-A', 'sms', t(D + 1));
assert.equal(r.allowed, false);

// 6. invalid input throws
await assert.rejects(reserve('', 'sms', t(0)), TypeError);
await assert.rejects(reserve('x', 'email', t(0)), TypeError);
await assert.rejects(reserve('x', 'sms', new Date('nope')), TypeError);
delete process.env.STATE_DIR;
await assert.rejects(reserve('x', 'sms', t(0)), /STATE_DIR/);
process.env.STATE_DIR = join(dir, 'nested', 'state');

// 7. concurrency across real processes: 8 workers x 4 attempts, same customer, same instant
const worker = `
import { reserve } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/baseline-g4-2/bot.mjs';
const now = new Date('2026-10-24T10:00:00Z');
const out = [];
for (let i = 0; i < 4; i++) out.push((await reserve('cust-C', ['sms','push','chat'][i%3], now)).allowed);
console.log(JSON.stringify(out));`;
const wfile = join(dir, 'worker.mjs');
const { writeFileSync } = await import('node:fs');
writeFileSync(wfile, worker);
const { execFile } = await import('node:child_process');
const runs = await Promise.all(Array.from({ length: 8 }, () => new Promise((res, rej) =>
  execFile(process.execPath, [wfile], { env: process.env }, (e, so, se) => e ? rej(new Error(se || e.message)) : res(JSON.parse(so)))
)));
const allowed = runs.flat().filter(Boolean).length;
console.log('concurrent allowed total:', allowed, 'of 32 attempts');
assert.equal(allowed, 5);

// 8. state file has no stale lock left behind
execFileSync('bash', ['-c', `ls -R "${process.env.STATE_DIR}" | grep -c lock || true`], { stdio: 'inherit' });
console.log('ALL CHECKS PASSED');
EOF
cd /tmp/bot-check && node check.mjs
